CREATE SCHEMA IF NOT EXISTS inventory;

CREATE TABLE IF NOT EXISTS inventory.stock_moves (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    state move_state NOT NULL DEFAULT 'draft',
    priority priority NOT NULL DEFAULT 'normal',
    create_date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    date TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    item_id UUID NOT NULL,
    demand_qty NUMERIC(18, 4) NOT NULL DEFAULT 0 CHECK (demand_qty >= 0),
    quantity NUMERIC(18, 4) NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    price_unit NUMERIC(18, 6) NOT NULL DEFAULT 0,
    procure_method procure_method NOT NULL DEFAULT 'make_to_stock',
    picking_id UUID,
    origin TEXT,
    location_id UUID NOT NULL,
    location_dest_id UUID NOT NULL,
    partner_id UUID,
    company_id UUID NOT NULL,
    rule_id UUID,
    warehouse_id UUID,
    orderpoint_id UUID,
    move_orig_ids UUID[] NOT NULL,
    move_dest_ids UUID[] NOT NULL,
    is_inventory BOOLEAN NOT NULL DEFAULT FALSE,
    scrapped BOOLEAN NOT NULL DEFAULT FALSE,
    propagate_cancel BOOLEAN NOT NULL DEFAULT TRUE,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

